look.customCSS:
/* ───── 灰与舞裙 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc0NCcgaGVpZ2h0PSc0NCc+PHBhdGggZD0nTTAgMjIgTDIyIDAgTDQ0IDIyIEwyMiA0NFonIGZpbGw9J25vbmUnIHN0cm9rZT0nI0U5RTJEOCcgc3Ryb2tlLXdpZHRoPScxJy8+PC9zdmc+") 0 0/44px 44px,#F4EFE8 !important}
[data-wk="body"]{background:transparent !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}

/* 顶栏底栏：象牙白浮板，底下一道淡影 */
[data-wk="chathead"]{background:#FBF8F3 !important;border-bottom:none !important;box-shadow:0 5px 0 #E6DED3,0 8px 14px rgba(120,100,80,.08) !important;gap:6px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#4A4440 !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.12em !important}
[data-wk="headdim"]{color:#A79E94 !important;white-space:nowrap !important;letter-spacing:.1em !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#4A4440 !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#4A4440 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:6px !important}

/* 头像：外面一圈钟面刻度 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important;box-shadow:0 0 0 2px #fff !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-26% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;border:none !important;border-radius:0 !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{inset:-18% !important}

/* 气泡：直角小卡，底下压一道厚边（像一级台阶的立面） */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:3px !important;letter-spacing:.08em !important;padding:11px 18px !important;border:none !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#E7DFD4 !important;color:#5C5249 !important;box-shadow:0 5px 0 #CFC4B5,0 9px 12px rgba(120,100,80,.10) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#8FA4C4 !important;color:#fff !important;box-shadow:0 5px 0 #6E83A3,0 9px 12px rgba(80,100,140,.15) !important}
/* 连发一级级错开：他往右走、你往左走，像王宫的台阶。一级 20px、最多三级；挪了多少这条就窄多少，长句子也不出界 */
[data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-left:20px !important;max-width:calc(100% - 20px) !important}
[data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{transform:none !important;margin-left:20px !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-left:40px !important;max-width:calc(100% - 40px) !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{transform:none !important;margin-left:40px !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-left:60px !important;max-width:calc(100% - 60px) !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{transform:none !important;margin-left:60px !important}
[data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-right:20px !important;max-width:calc(100% - 20px) !important}
[data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-right:40px !important;max-width:calc(100% - 40px) !important}
[data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{transform:none !important;margin-right:60px !important;max-width:calc(100% - 60px) !important}

/* 一串最后一条旁边，魔杖点一颗橘星 */
[data-wk="msg"][data-last="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-22px !important;top:50% !important;width:12px !important;height:16px !important;margin-top:-8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0U4ODEzQScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="1"][data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;left:-22px !important;top:50% !important;width:12px !important;height:16px !important;margin-top:-8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0U4ODEzQScvPjwvc3ZnPg==") center/contain no-repeat !important}

/* 时间：「今天 23:52」，旁边一只玻璃鞋，底下一行「在午夜之前」 */
[data-wk="time"]{display:flex !important;justify-content:center !important;position:relative !important;padding-bottom:14px !important}
[data-wk="time"] > span{display:inline-block !important;background:transparent !important;border:none !important;box-shadow:none !important;color:#4A4440 !important;letter-spacing:.15em !important;font-size:13px !important;padding:0 0 0 34px !important;background:url("data:image/svg+xml;base64,") left center/26px 14px no-repeat !important}
[data-wk="time"]::after{content:"在午夜之前" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:0 !important;text-align:center !important;font-size:9.5px !important;letter-spacing:.4em !important;color:#A79E94 !important}

/* 已读＝一颗橘色小钟；已送达＝灰色空心小钟 */
[data-wk="meta"]{color:#A79E94 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::after{content:"" !important;width:12px !important;height:12px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#E7DFD4 !important;border:none !important;border-radius:3px !important;box-shadow:0 5px 0 #CFC4B5 !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#E8813A !important}
[data-wk="name"]{color:#A79E94 !important}

/* 动描：没有框，灰烬色斜体，左边一道细细的竖线、线头点一颗橘星 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:transparent !important;border:none !important;border-left:1px solid #CFC4B5 !important;border-radius:0 !important;box-shadow:none !important;color:#8A7F74 !important;font-style:italic !important;font-size:13px !important;line-height:1.85 !important;letter-spacing:.06em !important;padding:2px 0 2px 16px !important;margin-left:10px !important}
[data-wk="narrink"]::before{content:"" !important;position:absolute !important;left:-5px !important;top:-8px !important;width:9px !important;height:12px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0U4ODEzQScvPjwvc3ZnPg==") center/contain no-repeat !important}
/* 系统提示：一行小字，前面一颗灰色空心小钟 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{border:none !important;color:#A79E94 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important;padding-left:16px !important;background:url("data:image/svg+xml;base64,") left center/11px 11px no-repeat !important}
[data-wk="sysnoteclose"]{color:#A79E94 !important}

/* 底栏：象牙白浮板；输入框是一条灰烬色的槽；最右那块雾蓝的是「让他回复」，发送是它左边的细箭头 */
[data-wk="composer"]{background:#FBF8F3 !important;border-top:none !important;box-shadow:0 -1px 0 #E6DED3,0 -6px 14px rgba(120,100,80,.06) !important;align-items:center !important;gap:10px !important}
[data-wk="chatinput"]{background:#EFE9E1 !important;border:none !important;border-radius:3px !important;color:#4A4440 !important;letter-spacing:.08em !important}
[data-wk="chatinput"]::placeholder{color:#B3A99E !important}
[data-wk="chatplus"],[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA0MCc+PHBhdGggZD0nTTIwIDEyIFYyOCBNMTIgMjAgSDI4JyBzdHJva2U9JyM0QTQ0NDAnIHN0cm9rZS13aWR0aD0nMS42JyBzdHJva2UtbGluZWNhcD0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA0MCc+PHBhdGggZD0nTTEyIDIwIEgyOCBNMjIgMTQgTDI4IDIwIEwyMiAyNicgZmlsbD0nbm9uZScgc3Ryb2tlPScjNEE0NDQwJyBzdHJva2Utd2lkdGg9JzEuNicgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJyBzdHJva2UtbGluZWpvaW49J3JvdW5kJy8+PC9zdmc+") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:58px !important;min-width:58px !important;height:40px !important;border:none !important;border-radius:3px !important;background:url("data:image/svg+xml;base64,") center/30px no-repeat,#8FA4C4 !important;box-shadow:0 5px 0 #6E83A3 !important;margin-bottom:5px !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active{transform:scale(.9) !important}
[data-wk="chatreply"]:active{transform:translateY(4px) !important;box-shadow:0 1px 0 #6E83A3 !important}
[data-wk="chatpanel"]{background:#FBF8F3 !important;border-top:1px solid #E6DED3 !important}
